mapper.select:
SELECT T1.PROPERTY_ID, T1.PROPERTY_NAME, T1.PROPERTY_KEY, T1.PROPERTY_VALUE, T1.PROPERTY_TYPE, T1.PROPERTY_DESC, T1.APPLICATION FROM LA_CONFIGS T1
T1.PROPERTY_KEY LIKE CONCAT(#{parameters.key}, '%')
AND T1.APPLICATION IN ('tenant_custom', 'tenant_system')
AND T1.APPLICATION = #{parameters.application}
AND T1.PROPERTY_NAME LIKE #{parameters.name}
ORDER BY T1.PROPERTY_KEY

SELECT T1.PROPERTY_ID, T1.PROPERTY_NAME, T1.PROPERTY_KEY, T1.PROPERTY_VALUE, T1.PROPERTY_TYPE, T1.PROPERTY_DESC, T1.APPLICATION, T2.OPTION_ID, T2.OPTION_NAME, T2.OPTION_VALUE, T2.OPTION_DESC FROM LA_CONFIGS T1 LEFT JOIN LA_CONFIG_OPTIONS T2 ON T1.PROPERTY_ID = T2.PROPERTY_ID AND T1.APPLICATION = T2.APPLICATION
T1.APPLICATION = #{application}
AND T1.PROPERTY_ID IN #{item}
